const WHITELIST = ['5591982250731']; // [] = responde a todos os contatos diretos
const EVOLUTION = 'http://evolution-api:8080';
const EVO_KEY = '7539443e08ab02320e9afd7d9b2149c9';
const INSTANCE = 'principal';
const CRM = 'http://sansol-crm:3000';
const WA_TOKEN = '45d0608818ca6462b540e615fc0b6f1ade82db2045b4d1dc';
const OLLAMA = 'http://host.docker.internal:11434';
const MODEL = 'llama3.1:8b';
const H_JSON = { 'Content-Type': 'application/json' };
const H_CRM = { 'Content-Type': 'application/json', 'x-webhook-token': WA_TOKEN };
const H_EVO = { 'Content-Type': 'application/json', apikey: EVO_KEY };

const http = async (o) => this.helpers.httpRequest(o);
const res = await http({ method: 'GET', url: CRM + '/api/wa/campaigns/pending', headers: H_CRM });
const items = res.items || [];
const out = [];
for (const it of items) {
  try {
    const sent = await http({ method: 'POST', url: EVOLUTION + '/message/sendText/' + INSTANCE, headers: H_EVO, body: { number: it.phone, text: it.text } });
    await http({ method: 'POST', url: CRM + '/api/wa/campaigns/recipient-sent', headers: H_CRM, body: { recipientId: it.recipientId, providerMessageId: sent?.key?.id } });
    out.push({ json: { phone: it.phone, status: 'sent' } });
  } catch (e) {
    await http({ method: 'POST', url: CRM + '/api/wa/campaigns/recipient-sent', headers: H_CRM, body: { recipientId: it.recipientId, error: String(e.message || e) } });
    out.push({ json: { phone: it.phone, status: 'failed' } });
  }
  await new Promise(r => setTimeout(r, 9000)); // intervalo anti-bloqueio
}
return out.length ? out : [{ json: { note: 'sem envios pendentes' } }];
